// Comparison helpers. Each names the field, because a golden-vector
// failure that says only "mismatch" costs more time than the test saved.
macro_rules! eq_fn {
    ($name:ident, $ty:ty) => {
        #[allow(dead_code)]
        fn $name(label: &str, actual: $ty, expected: $ty) -> Result<(), String> {
            if actual != expected {
                return Err(format!("{label}: expected {expected}, got {actual}"));
            }
            Ok(())
        }
    };
}

eq_fn!(eq_u8, u8);
eq_fn!(eq_u16, u16);
eq_fn!(eq_u32, u32);
eq_fn!(eq_u64, u64);
eq_fn!(eq_i64, i64);
eq_fn!(eq_bool, bool);

