    eq_u16("packet.version", h.version(), 1)?;
    eq_u16("packet.messageCount", h.message_count(), 6)?;
    eq_u8("packet.channel", h.channel(), 0)?;
    eq_u8("packet.flags", h.flags(), 0)?;
    eq_u64("packet.firstSequence", h.first_sequence(), 4294967294)?;
